import hashlib,json
from pathlib import Path
O=Path(__file__).resolve().parent;R=O.parent;I=R/'v14-final-composite-review-001/atkin-cusp-source-initial-001'
def sha(b):return hashlib.sha256(b).hexdigest()
def dig(x):return sha(json.dumps(x,sort_keys=True,separators=(',',':'),ensure_ascii=False).encode())
def save(n,x):(O/n).write_text(json.dumps(x,indent=2,ensure_ascii=False)+'\n',encoding='utf8')
uses=json.loads((I/'INITIAL-SOURCE-USES.json').read_bytes())['uses'];passages=json.loads((I/'INITIAL-PASSAGES.json').read_bytes())
raw=(R/'v14-atkin-cusp-input-author-001/PROOF.md').read_bytes()
reasons=[
 ('scope_boundary','Explicit limitation, not an assertion of eigen-action or finite cusp torsion.'),
 ('definition_and_elementary_calculation','Use the specified matrix definition. Since gcd(e,r)=1, Bezout supplies integers d,b with e*d-r*b=1, taking a=c=1; determinant is e*(e*a*d-r*b*c)=e. This uses only integer Bezout and determinant expansion, not the conclusion about cusp permutation.'),
 ('elementary_matrix_calculation','Direct multiplication by adj(M)/e gives the four displayed entries. The exact symbolic polynomial identity is checked independently of any eigenform theorem.'),
 ('local_group_argument','The entries and determinant show M*Gamma*M^-1 is contained in Gamma. Since M squared divided by e lies in Gamma, conjugation by M squared preserves Gamma, giving the reverse containment. Scalar e acts trivially on the upper half-plane, so the induced operator squares to the identity.'),
 ('definition_and_local_action_argument','The cusps of the analytic compactification are by definition the orbits Gamma0(N) backslash P1(Q). An invertible rational matrix acts bijectively on P1(Q); two-sided normalization makes its action well-defined and bijective on those orbits. No differential statement is needed.'),
 ('conditional_local_group_argument','The based quotient formula and definition of C_N as generated by cusp differences give membership in phi(C_N). If the separately supplied C_pi annihilates that group then it kills this element. No existence or numerical bound for C_pi is proved or imported here.')]
rows=[]
for u,p,(role,reason) in zip(uses,passages,reasons):
 l=p['location'];assert sha(raw)==l['pin']['sha256'];assert sha(b''.join(raw.splitlines(keepends=True)[l['start_line']-1:l['end_line']]))==l['excerpt_sha256']
 rows.append({'initial_use_id':u['id'],'initial_use_sha256':dig(u),'classification':u['classification'],'location':l,'source_role':role,'incoming_use_ids':[],'no_imports_reason':reason,'outgoing_provenance_use_ids':['ACTIVE-ATKIN-CUSP-PERMUTATION'] if role!='scope_boundary' else [],'caller_requirements':['Differential eigen-action and a finite cuspidal annihilator must be independently supplied wherever invoked.']})
save('RECONCILIATION.json',{'initial_source_uses_sha256':sha((I/'INITIAL-SOURCE-USES.json').read_bytes()),'initial_passages_sha256':sha((I/'INITIAL-PASSAGES.json').read_bytes()),'rows':rows,'scope':'Six source observations; elementary proof and definitions, not newform eigen-action or Manin-Drinfeld theorem.'})
save('CHECKS.json',{'six_exact_raw_passages':len(rows)==6,'initial_classifications_preserved':True,'no_output_as_incoming_use':True})
save('MANIFEST.json',{'files':{p.name:{'sha256':sha(p.read_bytes()),'bytes':p.stat().st_size} for p in sorted(O.iterdir()) if p.is_file() and p.name!='MANIFEST.json'}})
print(sha((O/'MANIFEST.json').read_bytes()))
